247	  static createMesh(
248	    proj: WorkProjectItem,
249	    size: WorkCardSize,
250	    detailPath: string,
251	    renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
252	  ): THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> & {
253	    userData: WorkCardUserData;
254	  } {
255	    const texture = WorkCard.buildTexture(proj, size, undefined, renderOptions);
256	    const geometry = new THREE.PlaneGeometry(size.w, size.h);
257	    const material = new THREE.MeshBasicMaterial({
258	      map: texture,
259	      transparent: true,
260	      opacity: 0,
261	    });
262	    const mesh = new THREE.Mesh(geometry, material) as THREE.Mesh<
263	      THREE.PlaneGeometry,
264	      THREE.MeshBasicMaterial
265	    > & { userData: WorkCardUserData };
266	    mesh.userData = { proj, detailPath };
267	    mesh.rotation.set(0, 0, 0);
268	    return mesh;
269	  }
270	
271	  static loadPlaceholderImage(
272	    url: string = WORK_PLACEHOLDER_IMAGE,
273	  ): Promise<HTMLImageElement> {
274	    return WorkCard.loadImage(url);
275	  }
276	
277	  /** 썸네일 등 임의 URL (CORS 가능 시 anonymous) */
278	  static loadImage(url: string): Promise<HTMLImageElement> {
279	    const trimmed = url.trim();
280	    return new Promise((resolve, reject) => {
281	      if (!trimmed) {
282	        reject(new Error("WorkCard: empty image url"));
283	        return;
284	      }
285	      const image = new Image();
286	      if (!trimmed.startsWith("data:") && !trimmed.startsWith("blob:")) {
287	        image.crossOrigin = "anonymous";
288	      }
289	      image.onload = () => resolve(image);
290	      image.onerror = () =>
291	        reject(new Error(`WorkCard: failed to load image ${trimmed}`));
292	      image.src = trimmed;
293	    });
294	  }
295	
296	  static updateTextureVideoFrame(
297	    texture: THREE.CanvasTexture,
298	    proj: WorkProjectItem,
299	    size: WorkCardSize,
300	    video: HTMLVideoElement,
301	    renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
302	  ): void {
303	    if (video.readyState < 2) return;
304	    const canvas = texture.image as HTMLCanvasElement;
305	    if (!canvas || !(canvas.getContext instanceof Function)) return;
306	    const ctx = canvas.getContext("2d");
307	    if (!ctx) return;
308	    const scale = canvas.width / CANVAS_W;
309	    const width = CANVAS_W;
310	    const height = Math.round((width * size.h) / size.w);
311	    const imageHeight = Math.round(width / IMAGE_ASPECT);
312	    ctx.setTransform(1, 0, 0, 1, 0, 0);
313	    ctx.clearRect(0, 0, canvas.width, canvas.height);
314	    ctx.setTransform(scale, 0, 0, scale, 0, 0);
315	    ctx.save();
316	    ctx.translate(0, height);
317	    ctx.scale(1, -1);
318	    const ratio = width / imageHeight;
319	    const vw = video.videoWidth;
320	    const vh = video.videoHeight;
321	    if (vw > 0 && vh > 0) {
322	      const videoRatio = vw / vh;
323	      let sw: number, sh: number, sx: number, sy: number;
324	      if (videoRatio > ratio) {
325	        sh = vh;
326	        sw = vh * ratio;
327	        sx = (vw - sw) / 2;
328	        sy = 0;
329	      } else {
330	        sw = vw;
331	        sh = vw / ratio;
332	        sx = 0;
333	        sy = (vh - sh) / 2;
334	      }
335	      ctx.drawImage(video, sx, sy, sw, sh, 0, 0, width, imageHeight);
336	    }
337	    drawTitleBar(ctx, proj, width, imageHeight, renderOptions);
338	    ctx.restore();
339	    texture.needsUpdate = true;
340	  }
341	
342	  static overlayVideoFrame(
343	    texture: THREE.CanvasTexture,
344	    size: WorkCardSize,
345	    video: HTMLVideoElement,
346	    alpha: number,
347	  ): void {
348	    if (video.readyState < 2) return;
349	    const canvas = texture.image as HTMLCanvasElement;
350	    if (!canvas || !(canvas.getContext instanceof Function)) return;
351	    const ctx = canvas.getContext("2d");
352	    if (!ctx) return;
353	    const scale = canvas.width / CANVAS_W;
354	    const width = CANVAS_W;
355	    const height = Math.round((width * size.h) / size.w);
356	    const imageHeight = Math.round(width / IMAGE_ASPECT);
357	    const ratio = width / imageHeight;
358	    const vw = video.videoWidth;
359	    const vh = video.videoHeight;
360	    if (vw === 0 || vh === 0) return;
361	    const videoRatio = vw / vh;
362	    let sw: number, sh: number, sx: number, sy: number;
363	    if (videoRatio > ratio) {
364	      sh = vh;
365	      sw = vh * ratio;
366	      sx = (vw - sw) / 2;
367	      sy = 0;
368	    } else {
369	      sw = vw;
370	      sh = vw / ratio;
371	      sx = 0;
372	      sy = (vh - sh) / 2;
373	    }
374	    ctx.save();
375	    ctx.setTransform(scale, 0, 0, scale, 0, 0);
376	    ctx.globalAlpha = alpha;
377	    ctx.translate(0, height);
378	    ctx.scale(1, -1);
379	    ctx.drawImage(video, sx, sy, sw, sh, 0, 0, width, imageHeight);
380	    ctx.restore();
381	    texture.needsUpdate = true;
382	  }
383	
384	  static offTextures(): void {
385	    texCache.forEach((texture) => texture.dispose());
386	    texCache.clear();
387	  }
388	}
