119	function migrateLegacyAboutTheatreState(
120	  savedState: Record<string, unknown>,
121	): Record<string, unknown> {
122	  const sheetsById = readAboutRecord(savedState.sheetsById);
123	  if (!sheetsById) {
124	    return savedState;
125	  }
126	  const nextSheetsById: Record<string, unknown> = {};
127	  let didChange = false;
128	
129	  Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
130	    const mappedSheetId =
131	      LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
132	    if (mappedSheetId !== sheetId) {
133	      didChange = true;
134	    }
135	    if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
136	      nextSheetsById[mappedSheetId] = sheetState;
137	      return;
138	    }
139	    didChange = true;
140	  });
141	
142	  if (!didChange) {
143	    return savedState;
144	  }
145	
146	  return {
147	    ...savedState,
148	    sheetsById: nextSheetsById,
149	  };
150	}
