180	  read(): WorksViewportSnapshot {
181	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
182	    return {
183	      width: snapshot.viewportWidth,
184	      height: snapshot.viewportHeight,
185	      dpr: Math.min(snapshot.render.clampedPixelRatio, this._pixelRatioMax),
