188	
189	  readHalfView(camera: THREE.Camera): WorksHalfViewBounds {
190	    if (camera instanceof THREE.OrthographicCamera) {
191	      return {
192	        hW: (camera.right - camera.left) * 0.5,
193	        hH: (camera.top - camera.bottom) * 0.5,
194	      };
195	    }
196	    const perspectiveCamera = camera as THREE.PerspectiveCamera;
197	    const fov = (perspectiveCamera.fov * Math.PI) / 180;
198	    const halfHeight = Math.tan(fov / 2) * perspectiveCamera.position.z;
199	    return {
200	      hW: halfHeight * perspectiveCamera.aspect,
201	      hH: halfHeight,
202	    };
203	  }
