226	class WorksCameraMotionRuntime {
227	  private readonly _layout: WorkLayoutConstants;
228	  private readonly _camPadX: number;
229	  private readonly _camPadY: number;
230	  private _baseCamZ: number;
231	  private _isDragging = false;
232	  private _dragPrevious: WorksPointerSample = { x: 0, y: 0 };
233	  private _targetX = 0;
234	  private _targetY = 0;
235	  private _velocityX = 0;
236	  private _velocityY = 0;
237	  private _targetZ: number;
238	  private _dynClampMinX: number;
239	  private _dynClampMaxX: number;
240	  private _dynClampMinY: number;
241	  private _dynClampMaxY: number;
242	
243	  constructor(
244	    layout: WorkLayoutConstants,
245	    camPadX: number,
246	    camPadY: number,
247	    camZ: number,
248	  ) {
249	    this._layout = layout;
250	    this._camPadX = camPadX;
251	    this._camPadY = camPadY;
252	    this._baseCamZ = camZ;
253	    this._targetZ = camZ;
254	    this._dynClampMinX = -camPadX;
255	    this._dynClampMaxX = camPadX;
256	    this._dynClampMinY = -camPadY;
257	    this._dynClampMaxY = camPadY;
258	  }
259	
260	  setDynamicClamp(positions: ReadonlyArray<WorksScatterPosition>): void {
261	    if (positions.length === 0) {
262	      this._dynClampMinX = this._dynClampMaxX = 0;
263	      this._dynClampMinY = this._dynClampMaxY = 0;
264	      return;
265	    }
266	    const MARGIN = 8;
267	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
268	    for (const p of positions) {
269	      if (p.x < minX) minX = p.x;
270	      if (p.x > maxX) maxX = p.x;
271	      if (p.y < minY) minY = p.y;
272	      if (p.y > maxY) maxY = p.y;
273	    }
274	    this._dynClampMinX = minX - MARGIN;
275	    this._dynClampMaxX = maxX + MARGIN;
276	    this._dynClampMinY = minY - MARGIN;
277	    this._dynClampMaxY = maxY + MARGIN;
278	  }
279	
280	  activateScatter(): void {
281	    this._targetZ = this._baseCamZ;
282	  }
283	
284	  setTargetPosition(targetX: number, targetY: number): void {
285	    this._targetX = targetX;
286	    this._targetY = targetY;
287	  }
288	
289	  setTargetZ(targetZ: number): void {
290	    this._targetZ = targetZ;
291	  }
292	
293	  readBaseCamZ(): number {
294	    return this._baseCamZ;
295	  }
296	
297	  setBaseCamZ(baseCamZ: number): void {
298	    this._baseCamZ = baseCamZ;
299	    this._targetZ = baseCamZ;
300	  }
301	
302	  primeFromCamera(camera: THREE.PerspectiveCamera): void {
303	    this._targetX = camera.position.x;
304	    this._targetY = camera.position.y;
305	    this._targetZ = camera.position.z;
306	  }
307	
308	  primeFromCameraPosition(targetX: number, targetY: number, targetZ: number): void {
309	    this._targetX = targetX;
310	    this._targetY = targetY;
311	    this._targetZ = targetZ;
312	  }
313	
314	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
315	    this._isDragging = true;
316	    this._dragPrevious = { ...pointer };
317	    this._velocityX = 0;
318	    this._velocityY = 0;
319	    this._targetX = camera.position.x;
320	    this._targetY = camera.position.y;
321	  }
322	
323	  endDrag(): void {
324	    this._isDragging = false;
325	  }
326	
327	  updateDrag(
328	    viewport: WorksViewportSnapshot,
329	    halfView: WorksHalfViewBounds,
330	    pointer: WorksPointerSample,
331	    velMultiplier = 1,
332	  ): void {
333	    if (!this._isDragging) return;
334	    const dx = pointer.x - this._dragPrevious.x;
335	    const dy = pointer.y - this._dragPrevious.y;
336	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
337	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
338	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
339	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7 * velMultiplier;
340	    this._targetX = Math.max(
341	      this._dynClampMinX + halfView.hW,
342	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
343	    );
344	    this._targetY = Math.max(
345	      this._dynClampMinY + halfView.hH,
346	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
347	    );
348	    this._dragPrevious = { ...pointer };
349	  }
350	
351	  updateFrame(camera: THREE.Camera, delta: number): void {
352	    if (this._isDragging) {
353	      const decay = Math.pow(this._layout.velDecay, delta * 60);
354	      this._velocityX *= decay;
355	      this._velocityY *= decay;
356	      this._targetX += this._velocityX * delta * 60;
357	      this._targetY += this._velocityY * delta * 60;
358	    }
359	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
360	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
361	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
362	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
363	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
364	    camera.lookAt(camera.position.x, camera.position.y, 0);
365	  }
366	
367	  get isDragging(): boolean {
368	    return this._isDragging;
369	  }
370	}
