451	      nextOffset: null,
452	      hasMore: false,
453	    };
454	    this._syncRootState();
455	    this._abortController?.abort();
456	    this._abortController = new AbortController();
457	    const grid = this._elements.grid;
458	    if (grid) grid.dataset.loading = "true";
459	    try {
460	      const response = await this._fetchItems(this._resolveInitialOffset());
461	      this._appendItems(response.items);
462	      this._feedState = {
463	        nextOffset: response.nextOffset,
464	        hasMore: response.hasMore,
465	      };
466	      this._syncRootState();
467	      this._syncPaginationVisibility();
468	      this._attachSentinel();
